use std::collections::{HashMap, LinkedList};
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::sync::Mutex;
use tokio::task::JoinHandle;

type EvictReason = &'static str; // "expired", "lru", "memory"

struct CacheEntry<V> {
    value: V,
    expires_at: Instant,
    size: usize,
    last_accessed: Instant,
    access_count: u64,
}

pub struct CacheConfig {
    pub max_entries: usize,
    pub default_ttl: Duration,
    pub max_memory_bytes: usize,
    pub eviction_check_interval: Duration,
    pub on_evict: Option<Box<dyn Fn(&str, EvictReason) + Send + Sync>>,
}

impl Default for CacheConfig {
    fn default() -> Self {
        Self {
            max_entries: 1000,
            default_ttl: Duration::from_secs(60),
            max_memory_bytes: 100 * 1024 * 1024,
            eviction_check_interval: Duration::from_secs(5),
            on_evict: None,
        }
    }
}

#[derive(Default, Clone, Debug)]
pub struct Stats {
    pub hits: u64,
    pub misses: u64,
    pub evictions: u64,
    pub expirations: u64,
}

pub struct LRUCache<V> {
    entries: HashMap<String, CacheEntry<V>>,
    access_order: LinkedList<String>,
    config: Arc<CacheConfig>,
    current_memory: usize,
    stats: Stats,
}

impl<V> LRUCache<V> {
    pub fn new(config: CacheConfig) -> Self {
        Self {
            entries: HashMap::new(),
            access_order: LinkedList::new(),
            config: Arc::new(config),
            current_memory: 0,
            stats: Stats::default(),
        }
    }

    pub fn get(&mut self, key: &str) -> Option<&V> {
        // Check existence and expiration first
        let expired = self.entries.get(key).map(|e| Instant::now() > e.expires_at);
        match expired {
            None => {
                self.stats.misses += 1;
                None
            }
            Some(true) => {
                self.delete(key, "expired");
                self.stats.misses += 1;
                None
            }
            Some(false) => {
                let now = Instant::now();
                let entry = self.entries.get_mut(key).unwrap();
                entry.last_accessed = now;
                entry.access_count += 1;
                self.move_to_front(key);
                self.stats.hits += 1;
                Some(&self.entries.get(key).unwrap().value)
            }
        }
    }

    pub fn put(&mut self, key: &str, value: V, ttl: Option<Duration>, size: Option<usize>) {
        let size = size.unwrap_or(std::mem::size_of::<V>());
        let ttl = ttl.unwrap_or(self.config.default_ttl);

        if let Some(old) = self.entries.get(key) {
            self.current_memory -= old.size;
        }

        while self.current_memory + size > self.config.max_memory_bytes && !self.access_order.is_empty() {
            self.evict_lru("memory");
        }

        while self.entries.len() >= self.config.max_entries && !self.access_order.is_empty() {
            self.evict_lru("lru");
        }

        let now = Instant::now();
        let entry = CacheEntry {
            value,
            expires_at: now + ttl,
            size,
            last_accessed: now,
            access_count: 0,
        };

        self.entries.insert(key.to_owned(), entry);
        self.current_memory += size;
        self.move_to_front(key);
    }

    pub fn delete(&mut self, key: &str, reason: EvictReason) -> bool {
        if let Some(entry) = self.entries.remove(key) {
            self.current_memory -= entry.size;
            self.access_order = self.access_order.iter().filter(|k| k.as_str() != key).cloned().collect();
            if reason == "expired" {
                self.stats.expirations += 1;
            } else {
                self.stats.evictions += 1;
            }
            if let Some(ref cb) = self.config.on_evict {
                cb(key, reason);
            }
            true
        } else {
            false
        }
    }

    pub fn has(&mut self, key: &str) -> bool {
        let expired = self.entries.get(key).map(|e| Instant::now() > e.expires_at);
        match expired {
            None => false,
            Some(true) => { self.delete(key, "expired"); false }
            Some(false) => true,
        }
    }

    pub fn size(&self) -> usize { self.entries.len() }
    pub fn memory_usage(&self) -> usize { self.current_memory }
    pub fn get_stats(&self) -> Stats { self.stats.clone() }

    pub fn clear(&mut self) {
        let keys: Vec<String> = self.entries.keys().cloned().collect();
        for key in keys {
            self.delete(&key, "lru");
        }
    }

    pub fn evict_expired(&mut self) {
        let now = Instant::now();
        let expired: Vec<String> = self.entries.iter()
            .filter(|(_, e)| now > e.expires_at)
            .map(|(k, _)| k.clone())
            .collect();
        for key in expired {
            self.delete(&key, "expired");
        }
    }

    pub fn keys(&self) -> Vec<&str> {
        self.access_order.iter().map(|s| s.as_str()).collect()
    }

    fn move_to_front(&mut self, key: &str) {
        self.access_order = self.access_order.iter().filter(|k| k.as_str() != key).cloned().collect();
        self.access_order.push_front(key.to_owned());
    }

    fn evict_lru(&mut self, reason: EvictReason) {
        if let Some(oldest) = self.access_order.pop_back() {
            self.delete(&oldest, reason);
        }
    }
}

/// Wrapper for async eviction loop
pub struct AsyncLRUCache<V: Send + 'static> {
    inner: Arc<Mutex<LRUCache<V>>>,
    eviction_handle: Option<JoinHandle<()>>,
}

impl<V: Send + 'static> AsyncLRUCache<V> {
    pub fn new(config: CacheConfig) -> Self {
        Self {
            inner: Arc::new(Mutex::new(LRUCache::new(config))),
            eviction_handle: None,
        }
    }

    pub fn inner(&self) -> &Arc<Mutex<LRUCache<V>>> {
        &self.inner
    }

    pub fn start_eviction_loop(&mut self) {
        if self.eviction_handle.is_some() { return; }
        let cache = self.inner.clone();
        let interval = {
            // We need to read the interval; block_on won't work inside async, so we spawn
            // We'll just store it. Actually we can't easily read it without locking.
            // We'll capture the arc and read inside the task.
            Duration::from_millis(30) // placeholder, will read inside
        };
        let _ = interval;
        let handle = tokio::spawn(async move {
            let interval_dur = {
                let lock = cache.lock().await;
                lock.config.eviction_check_interval
            };
            let mut interval = tokio::time::interval(interval_dur);
            loop {
                interval.tick().await;
                let mut lock = cache.lock().await;
                lock.evict_expired();
            }
        });
        self.eviction_handle = Some(handle);
    }

    pub fn stop_eviction_loop(&mut self) {
        if let Some(handle) = self.eviction_handle.take() {
            handle.abort();
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tokio::time::sleep;

    #[test]
    fn basic_get_put() {
        let mut cache = LRUCache::new(CacheConfig { max_entries: 3, default_ttl: Duration::from_millis(100), ..Default::default() });
        cache.put("a", "hello", None, None);
        assert_eq!(cache.get("a"), Some(&"hello"));
        assert_eq!(cache.size(), 1);
    }

    #[test]
    fn lru_eviction() {
        let mut cache = LRUCache::new(CacheConfig { max_entries: 3, default_ttl: Duration::from_secs(60), ..Default::default() });
        cache.put("a", "hello", None, None);
        cache.put("b", "world", None, None);
        cache.put("c", "foo", None, None);
        cache.put("d", "bar", None, None); // evicts 'a'
        assert!(!cache.has("a"));
        assert!(cache.has("d"));
    }

    #[tokio::test]
    async fn ttl_expiration() {
        let mut cache = LRUCache::new(CacheConfig { max_entries: 3, default_ttl: Duration::from_millis(100), ..Default::default() });
        cache.put("x", "temp", Some(Duration::from_millis(50)), None);
        sleep(Duration::from_millis(80)).await;
        assert_eq!(cache.get("x"), None);
    }

    #[test]
    fn access_order() {
        let mut cache = LRUCache::new(CacheConfig { max_entries: 3, default_ttl: Duration::from_secs(60), ..Default::default() });
        cache.put("1", "one", None, None);
        cache.put("2", "two", None, None);
        cache.put("3", "three", None, None);
        cache.get("1"); // access '1', '2' becomes LRU
        cache.put("4", "four", None, None); // evicts '2'
        assert!(!cache.has("2"));
        assert!(cache.has("1"));
    }

    #[test]
    fn stats() {
        let mut cache = LRUCache::new(CacheConfig { max_entries: 3, default_ttl: Duration::from_secs(60), ..Default::default() });
        cache.put("a", "hello", None, None);
        cache.get("a"); // hit
        cache.get("z"); // miss
        let stats = cache.get_stats();
        assert!(stats.hits > 0);
        assert!(stats.misses > 0);
    }

    #[tokio::test]
    async fn eviction_loop() {
        let mut async_cache = AsyncLRUCache::new(CacheConfig {
            max_entries: 10,
            default_ttl: Duration::from_millis(50),
            eviction_check_interval: Duration::from_millis(30),
            ..Default::default()
        });
        {
            let mut cache = async_cache.inner().lock().await;
            cache.put("e1", "val1", None, None);
        }
        async_cache.start_eviction_loop();
        sleep(Duration::from_millis(150)).await;
        {
            let mut cache = async_cache.inner().lock().await;
            assert!(!cache.has("e1"));
        }
        async_cache.stop_eviction_loop();
    }
}
